insert into public.course_content_draft (course_id, what_you_build, what_you_learn, session, starter_code, test_it_out, troubleshooting, resources, tier, change_note)
values (
  11,
  $wyb$A morning script that reads today's Google Calendar events and your open tasks, asks Claude to turn both into a realistic time-blocked plan, and saves it as a plain-text file you can open (or print) before your day starts. Every parsing and formatting piece is unit-tested against realistic fake data first, so you can trust the code before you ever touch a live Google account, and the plan-generation step checks the AI's reply for dropped or duplicated tasks before you ever see it.$wyb$,
  $wyl$["Authenticate with a real Google API using OAuth 2.0, not a service account or API key", "Convert Google Calendar's raw JSON (including all-day events) into a clean, predictable shape", "Read and normalize a plain-text task list without needing any external account", "Design a bracket-marker prompt format that degrades gracefully instead of crashing on malformed AI output", "Write a coverage check that catches an AI dropping or duplicating a task before you trust the output", "Call the AI through a shared, credit-metered gateway instead of a personal API key", "Wire independently-tested pieces into one script you could actually schedule to run every morning"]$wyl$::jsonb,
  $sess${"model": "Claude Haiku 4.5 (via your AI Builder credits)", "totalTime": "140 min", "buildCount": 6, "whatYouNeed": ["Your AI Builder key (Credits page on your dashboard)", "Python 3.10+ installed", "A free Google Cloud account (console.cloud.google.com)", "A Google Calendar (a personal Gmail calendar works fine)"], "outcomes": ["Pull today's real events straight from your Google Calendar via OAuth", "Turn a plain-text task list into something an AI prompt can use", "Have the AI turn both into a time-blocked plan with a Morning / Afternoon / Evening structure", "Catch the AI if it drops or double-books a task, instead of trusting it blindly", "Save (and print) a plan file you could hook up to a daily scheduled task"], "builds": [{"number": 1, "title": "Parse real Google Calendar data -- before you touch OAuth", "time": "25 min", "description": "Google's Calendar API returns two different shapes for an event depending on whether it's timed or all-day, and the fastest way to learn that shape is against a fake copy of it you already have -- not live, while also fighting a browser consent screen. This build writes and tests every parsing helper calendar_client.py needs.", "steps": [{"instruction": "Create `calendar_client.py` with this code:", "prompt": "\"\"\"\nStep 1 of the Calendar & Task Prioritizer Agent.\n\nLogs into Google Calendar and turns its raw JSON reply into the small,\nclean list of dicts the rest of this project works with.\n\"\"\"\n\nimport datetime\nimport os\n\nfrom google.auth.transport.requests import Request\nfrom google.oauth2.credentials import Credentials\nfrom google_auth_oauthlib.flow import InstalledAppFlow\nfrom googleapiclient.discovery import build\n\n# Read-only is the correct scope here. This project only ever reads your\n# calendar to build a plan - it never creates, edits or deletes an event.\n# Asking for the narrowest scope that does the job is good practice, and\n# it also means the Google consent screen shows a shorter, less alarming\n# permission list to whoever approves it (you, or a test user you add).\nSCOPES = [\"https://www.googleapis.com/auth/calendar.readonly\"]\n\nTOKEN_FILE = \"token.json\"\nCREDENTIALS_FILE = \"credentials.json\"\n\n\ndef get_calendar_service():\n    \"\"\"\n    Returns an authenticated Google Calendar API client.\n\n    The first time you run this, a browser tab opens asking you to log in\n    and approve access - that's the OAuth \"consent screen\". Approve it and\n    a token.json file is written next to this one, so every run after that\n    is silent. Delete token.json if you ever need to log in again (e.g. you\n    revoked access, or you want to switch Google accounts).\n    \"\"\"\n    creds = None\n    if os.path.exists(TOKEN_FILE):\n        creds = Credentials.from_authorized_user_file(TOKEN_FILE, SCOPES)\n\n    # Tokens expire after about an hour. Refreshing silently with the\n    # long-lived refresh token is much less annoying than re-opening a\n    # browser tab to log in again every time you run this.\n    if creds and creds.expired and creds.refresh_token:\n        creds.refresh(Request())\n    elif not creds or not creds.valid:\n        if not os.path.exists(CREDENTIALS_FILE):\n            raise FileNotFoundError(\n                f\"Missing {CREDENTIALS_FILE}.\\n\"\n                \"Download it from Google Cloud Console (see README Build 2) \"\n                \"and put it in this same folder, then run this again.\"\n            )\n        flow = InstalledAppFlow.from_client_secrets_file(CREDENTIALS_FILE, SCOPES)\n        creds = flow.run_local_server(port=0)\n        with open(TOKEN_FILE, \"w\") as token:\n            token.write(creds.to_json())\n\n    return build(\"calendar\", \"v3\", credentials=creds)\n\n\ndef fetch_todays_events(service, calendar_id=\"primary\"):\n    \"\"\"\n    Asks Google for today's raw events.\n\n    Deliberately split from get_today_events() below so the parsing logic\n    (parse_events, further down) can be unit-tested against a realistic\n    fake response dict without ever touching the network or needing a\n    real Google account - which matters because this course can't assume\n    every student has one, or that a live OAuth flow can be verified from\n    an automated test.\n    \"\"\"\n    today_start = datetime.datetime.now().replace(hour=0, minute=0, second=0, microsecond=0)\n    today_end = today_start + datetime.timedelta(days=1)\n\n    return service.events().list(\n        calendarId=calendar_id,\n        timeMin=today_start.isoformat() + \"Z\",\n        timeMax=today_end.isoformat() + \"Z\",\n        singleEvents=True,\n        orderBy=\"startTime\",\n    ).execute()\n\n\ndef _clock_time(when):\n    \"\"\"\n    Pulls just the HH:MM out of a Calendar API dateTime string, dropping\n    the date and timezone offset - the prompt only needs to know when in\n    the day something happens, not a full ISO timestamp.\n\n        \"2026-09-02T09:00:00+01:00\" -> \"09:00\"\n    \"\"\"\n    raw = when.get(\"dateTime\", \"\")\n    return raw[11:16] if len(raw) >= 16 else raw\n\n\ndef parse_events(response):\n    \"\"\"\n    Turns Google's raw Calendar API response into the small, clean shape\n    the rest of this project uses:\n\n        [{\"summary\": \"Standup\", \"start\": \"09:00\", \"end\": \"09:15\", \"all_day\": False}, ...]\n\n    Google represents two different kinds of events with two different\n    keys, and this is the one place that deals with the difference:\n\n    - Timed events:   start = {\"dateTime\": \"2026-09-02T09:00:00+01:00\"}\n    - All-day events: start = {\"date\": \"2026-09-02\"}                <- no time at all!\n\n    Skip that distinction and an all-day event crashes the whole run with\n    a KeyError the first time your calendar has one - which, for most\n    people, is more often than you'd think (birthdays, holidays, and\n    \"deadline\" reminders people put on the calendar as all-day entries).\n    \"\"\"\n    events = []\n    for item in response.get(\"items\", []):\n        start = item.get(\"start\", {})\n        end = item.get(\"end\", {})\n        is_all_day = \"dateTime\" not in start\n\n        events.append({\n            \"summary\": item.get(\"summary\", \"(no title)\"),\n            \"start\": \"all day\" if is_all_day else _clock_time(start),\n            \"end\": \"all day\" if is_all_day else _clock_time(end),\n            \"all_day\": is_all_day,\n        })\n    return events\n\n\ndef get_today_events(calendar_id=\"primary\"):\n    \"\"\"\n    The one function main.py actually calls: authenticate, fetch, parse.\n\n        events = get_today_events()\n    \"\"\"\n    service = get_calendar_service()\n    response = fetch_todays_events(service, calendar_id)\n    return parse_events(response)\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the parsing logic works - no live\n    # Google account, browser login or network access required:\n    #     python calendar_client.py\n    #\n    # This is a realistic shape for what the Calendar API actually\n    # returns (see https://developers.google.com/calendar/api/v3/reference/events/list),\n    # not a simplified stand-in for it.\n    fake_response = {\n        \"items\": [\n            {\n                \"summary\": \"Team standup\",\n                \"start\": {\"dateTime\": \"2026-09-02T09:00:00+01:00\"},\n                \"end\": {\"dateTime\": \"2026-09-02T09:15:00+01:00\"},\n            },\n            {\n                \"summary\": \"Company holiday\",\n                \"start\": {\"date\": \"2026-09-02\"},\n                \"end\": {\"date\": \"2026-09-03\"},\n            },\n            {\n                \"summary\": \"Client call\",\n                \"start\": {\"dateTime\": \"2026-09-02T14:30:00+01:00\"},\n                \"end\": {\"dateTime\": \"2026-09-02T15:00:00+01:00\"},\n            },\n        ]\n    }\n\n    result = parse_events(fake_response)\n    print(f\"Parsed {len(result)} events:\\n\")\n    for event in result:\n        when = \"all day\" if event[\"all_day\"] else f\"{event['start']}-{event['end']}\"\n        print(f\"  {when:>14}  {event['summary']}\")\n\n    assert len(result) == 3\n    assert result[0][\"start\"] == \"09:00\" and result[0][\"end\"] == \"09:15\"\n    assert result[1][\"all_day\"] is True and result[1][\"start\"] == \"all day\"\n    assert result[2][\"summary\"] == \"Client call\" and result[2][\"all_day\"] is False\n\n    # An empty calendar day is a real case (weekends, holidays) and must\n    # not crash - it should just produce an empty list.\n    assert parse_events({\"items\": []}) == []\n    assert parse_events({}) == []\n\n    print(\"\\nAll checks passed.\")\n", "verify": "Run `python calendar_client.py`. You should see `Parsed 3 events:` followed by three lines -- two showing real times and one showing `all day` for the Company holiday -- and finally `All checks passed.`"}], "goFurther": "Add a fourth fake event whose `start` dict has neither `dateTime` nor `date` at all (a genuinely malformed API response). Confirm `parse_events` still returns something for it instead of raising -- `is_all_day = \"dateTime\" not in start` means it gets treated as all-day rather than crashing, which is the safer default when a response doesn't match the shape you expected."}, {"number": 2, "title": "Connect to your real Google Calendar", "time": "25 min", "description": "OAuth is the one part of this project you can't fake -- it needs your actual Google account and a real consent screen. This build is mostly clicking through Google Cloud Console, then running the login flow calendar_client.py already has from Build 1.", "steps": [{"instruction": "In your browser, go to console.cloud.google.com and create a new project (any name, e.g. \"Calendar Prioritizer\"). Go to APIs & Services > Library, search for \"Google Calendar API\", and click Enable."}, {"instruction": "Still in Google Cloud Console, go to APIs & Services > OAuth consent screen, choose \"External\", fill in an app name and your email, and add your own Google account as a Test User (apps in \"Testing\" mode only allow logins from accounts on that list). Then go to Credentials > Create Credentials > OAuth client ID, choose \"Desktop app\", and download the JSON file. Rename it to exactly `credentials.json` and put it in the same folder as `calendar_client.py`."}, {"instruction": "Test the real login. In your terminal, run:", "prompt": "python -c \"from calendar_client import get_calendar_service; get_calendar_service(); print('Logged in. token.json saved.')\"", "verify": "A browser tab opens asking you to log in to Google and approve read-only access to your calendar. After you approve it, your terminal prints `Logged in. token.json saved.` and a new `token.json` file appears in your project folder."}], "goFurther": "Go to myaccount.google.com/permissions, find this app, and click Remove Access. Run the login test again -- Google makes you re-approve, and a fresh token.json is written. This is why SCOPES only asks for calendar.readonly: even a leaked or revoked token can only ever read your calendar, never create, move, or delete an event on it."}, {"number": 3, "title": "Read your task list", "time": "15 min", "description": "Not every part of this project needs an external account -- your task list is just a text file, so the code that reads it can be fully written and tested right now, no Google or AI account required.", "steps": [{"instruction": "Create `tasks.py` with this code:", "prompt": "\"\"\"\nStep 2 of the Calendar & Task Prioritizer Agent.\n\nReads your task list. Deliberately boring: a plain text file, one task per\nline. No task-manager account, no API, no OAuth - just something you can\nopen and edit in two seconds when your day changes.\n\"\"\"\n\nimport os\n\nDEFAULT_TASKS_FILE = \"tasks.txt\"\n\n# Written to tasks.txt the first time this runs, so the project works out\n# of the box before you've written your own list - you see the expected\n# format instead of the program crashing on a missing file.\nSAMPLE_TASKS = [\n    \"Finish the Q3 budget review\",\n    \"Reply to the vendor contract email\",\n    \"Prepare slides for Friday's demo\",\n    \"Review pull request #482\",\n    \"Book the dentist appointment\",\n]\n\n\ndef clean_task_line(line):\n    \"\"\"\n    Strips one raw line from tasks.txt down to the task text, or returns\n    \"\" if the line isn't a task at all (blank, or a \"# comment\").\n\n    Split out from get_tasks() below so it can be tested against a list\n    of fake lines without needing a real tasks.txt on disk.\n    \"\"\"\n    stripped = line.strip()\n    if not stripped or stripped.startswith(\"#\"):\n        return \"\"\n\n    # People naturally write \"- Finish the report\" or \"* Finish the\n    # report\" in a plain text list. Strip the common leading markers so\n    # they don't end up as literal characters inside the AI prompt later.\n    for marker in (\"- \", \"* \"):\n        if stripped.startswith(marker):\n            stripped = stripped[len(marker):]\n            break\n\n    return stripped.strip()\n\n\ndef get_tasks(path=DEFAULT_TASKS_FILE):\n    \"\"\"\n    Returns your tasks as a list of plain strings, one per line.\n\n        tasks = get_tasks()\n\n    Creates tasks.txt with sample tasks the first time it's called, so\n    running main.py before you've customised anything still works and\n    shows you what the file should look like, instead of crashing.\n    \"\"\"\n    if not os.path.exists(path):\n        _write_sample_file(path)\n\n    with open(path, \"r\", encoding=\"utf-8\") as f:\n        lines = f.readlines()\n\n    cleaned = [clean_task_line(line) for line in lines]\n    return [task for task in cleaned if task]\n\n\ndef _write_sample_file(path):\n    with open(path, \"w\", encoding=\"utf-8\") as f:\n        f.write(\"# One task per line. Lines starting with # are ignored.\\n\")\n        for task in SAMPLE_TASKS:\n            f.write(f\"- {task}\\n\")\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the line-cleaning logic works:\n    #     python tasks.py\n    fake_lines = [\n        \"- Finish the Q3 budget review\\n\",\n        \"\\n\",\n        \"# this is a comment, skip it\\n\",\n        \"* Reply to the vendor contract email\\n\",\n        \"Book the dentist appointment\\n\",\n        \"   \\n\",\n    ]\n\n    cleaned = [clean_task_line(line) for line in fake_lines]\n    cleaned = [task for task in cleaned if task]\n\n    print(f\"Cleaned {len(cleaned)} tasks from {len(fake_lines)} raw lines:\\n\")\n    for task in cleaned:\n        print(f\"  - {task}\")\n\n    assert cleaned == [\n        \"Finish the Q3 budget review\",\n        \"Reply to the vendor contract email\",\n        \"Book the dentist appointment\",\n    ]\n    print(\"\\nAll checks passed.\")\n", "verify": "Run `python tasks.py`. You should see `Cleaned 3 tasks from 6 raw lines:` followed by the three real tasks with their markers stripped (the blank line and the comment line are dropped), then `All checks passed.`"}], "goFurther": "Delete tasks.txt entirely, then run `python -c \"from tasks import get_tasks; print(get_tasks())\"` in that same folder. Confirm it creates tasks.txt with the 5 sample tasks and returns them, instead of crashing on a missing file -- that's the difference between a tool a beginner can open cold and one that needs a setup step nobody wrote down."}, {"number": 4, "title": "Build the AI prioritizer", "time": "30 min", "description": "This is the one point in the whole project where the AI gets called. It has to turn a fixed calendar and an open task list into a plan without inventing events, silently dropping a task, or scheduling the same task twice -- three ways this kind of request can go wrong that a prompt alone can ask for but never guarantee.", "steps": [{"instruction": "Create `prioritizer.py` with this code:", "prompt": "\"\"\"\nStep 3 of the Calendar & Task Prioritizer Agent - the actual \"prioritizer\".\n\nBuilds one prompt out of today's calendar events and open tasks, asks the\nAI for a plan, and turns its reply into time-of-day blocks you can read,\nprint, or hand to main.py to save as a file.\n\"\"\"\n\nfrom sdt_ai import ask_ai\n\n# Three broad blocks rather than exact time slots. Asking the AI to place\n# things at precise minutes (like \"09:07\") invites it to invent precision\n# it doesn't have - it doesn't know how long your commute is or how\n# focused you'll actually be. Morning/afternoon/evening is honest about\n# what an AI reading a calendar and a to-do list can judge well (relative\n# priority, rough sequencing), and not what it can't (your real day).\nSECTIONS = [\"MORNING\", \"AFTERNOON\", \"EVENING\"]\n\n# Anything that doesn't fit lands here instead of vanishing. This section\n# only appears in the AI's reply when something is genuinely left over.\nOVERFLOW_SECTION = \"UNSCHEDULED\"\n\nALL_SECTIONS = SECTIONS + [OVERFLOW_SECTION]\n\n\ndef format_events_for_prompt(events):\n    \"\"\"Turns the list of event dicts from calendar_client into readable\n    lines for the prompt. Kept separate so build_prompt stays skimmable.\"\"\"\n    if not events:\n        return \"(no calendar events today)\"\n    lines = []\n    for event in events:\n        when = \"all day\" if event[\"all_day\"] else f\"{event['start']}-{event['end']}\"\n        lines.append(f\"- {when}: {event['summary']}\")\n    return \"\\n\".join(lines)\n\n\ndef format_tasks_for_prompt(tasks):\n    if not tasks:\n        return \"(no open tasks)\"\n    return \"\\n\".join(f\"- {task}\" for task in tasks)\n\n\ndef build_prompt(events, tasks):\n    \"\"\"\n    Writes the instructions sent to the AI. Kept in its own function so\n    you can print it and read exactly what's being asked - the fastest\n    way to fix a plan you don't like is to fix the prompt, not to argue\n    with the AI about it.\n    \"\"\"\n    return f\"\"\"You are a calendar assistant. Build today's plan from the\nfixed calendar events and open tasks listed below.\n\nTODAY'S CALENDAR EVENTS (fixed - do not move them or invent new ones):\n{format_events_for_prompt(events)}\n\nOPEN TASKS (fit these around the events above, in priority order):\n{format_tasks_for_prompt(tasks)}\n\nRules:\n- Every calendar event listed above must appear in the plan exactly once.\n- Every task listed above must appear in the plan exactly once. If a task\n  genuinely will not fit anywhere today, still list it - in an\n  [{OVERFLOW_SECTION}] section at the end - with a one-line reason why.\n- Do not invent tasks or events that were not given to you.\n\nFormat your answer EXACTLY like this, with the section name in square\nbrackets on its own line, then bullet points underneath it. Use only the\nsection names below, in this order, and skip a section entirely if\nnothing belongs in it:\n\n[MORNING]\n- ...\n\n[AFTERNOON]\n- ...\n\n[EVENING]\n- ...\n\n[{OVERFLOW_SECTION}]\n- ...\n\nAfter the last section, write [END] on its own line.\n\nDo not add any explanation, introduction or closing remark.\n\"\"\"\n\n\ndef split_plan(reply):\n    \"\"\"\n    Turns the AI's one long answer into a dict, one entry per section:\n\n        {\"MORNING\": \"- ...\\n- ...\", \"AFTERNOON\": \"...\", ...}\n\n    Same [MARKER] approach as the Social Post Generator project, for the\n    same reason: markers degrade gracefully (a line we don't recognise is\n    simply ignored) where asking for JSON instead degrades by crashing\n    the whole program the first time the AI adds a stray comma.\n    \"\"\"\n    plan = {}\n    current_section = None\n    current_lines = []\n\n    for line in reply.splitlines():\n        stripped = line.strip()\n        marker = stripped.strip(\"[]\").upper()\n        is_marker = stripped.startswith(\"[\") and stripped.endswith(\"]\")\n\n        # [END] tells us the plan is finished. Without it, a friendly\n        # sign-off like \"Let me know if you'd like adjustments!\" gets\n        # glued onto the last section and saved into your plan file.\n        if is_marker and marker == \"END\":\n            break\n\n        if is_marker and marker in ALL_SECTIONS:\n            if current_section:\n                plan[current_section] = \"\\n\".join(current_lines).strip()\n            current_section = marker\n            current_lines = []\n        elif current_section:\n            # The AI sometimes wraps its whole answer in ``` code fences.\n            # Those aren't part of the plan, so drop them.\n            if stripped.startswith(\"```\"):\n                continue\n            current_lines.append(line)\n\n    if current_section:\n        plan[current_section] = \"\\n\".join(current_lines).strip()\n\n    return plan\n\n\ndef check_plan_coverage(plan, tasks):\n    \"\"\"\n    Compares the parsed plan against the original task list and reports\n    anything that looks wrong, INSTEAD OF trusting that the AI followed\n    the \"every task exactly once\" rule we asked for in the prompt.\n\n    Returns a list of human-readable warning strings (empty if the plan\n    looks complete). Two specific failure modes this catches, because\n    they are the two ways a plan that \"looks fine at a glance\" quietly\n    loses real work:\n\n    - A DROPPED task: it never appears anywhere in the reply. Easy to\n      miss when skimming a long plan - you only notice at 4pm that the\n      thing you asked about never got scheduled at all.\n    - A DOUBLE-BOOKED task: the same task text shows up in more than one\n      section. This happens more than you'd expect when a model is asked\n      to both \"prioritise\" and \"don't drop anything\" for an ambiguous\n      task - it sometimes hedges by placing it in two blocks instead of\n      picking one.\n\n    This is substring matching on the task text, not exact matching -\n    the AI usually restates a task with a little of its own phrasing\n    around it (e.g. adding a time or a note), so requiring an identical\n    string would produce false \"DROPPED\" warnings on a plan that is\n    actually fine.\n    \"\"\"\n    warnings = []\n\n    for task in tasks:\n        task_lower = task.lower()\n        appearances = sum(\n            1 for section_text in plan.values() if task_lower in section_text.lower()\n        )\n\n        if appearances == 0:\n            warnings.append(f'DROPPED: \"{task}\" does not appear anywhere in the plan.')\n        elif appearances > 1:\n            warnings.append(f'DOUBLE-BOOKED: \"{task}\" appears in {appearances} sections.')\n\n    return warnings\n\n\ndef plan_day(events, tasks):\n    \"\"\"\n    The main function. Give it events and tasks, get back a checked plan.\n\n        result = plan_day(events, tasks)\n        print(result[\"plan\"])\n        print(result[\"warnings\"])\n\n    Returns a dict rather than raw text because a plan you can't verify\n    isn't a plan you can trust with your actual day - this hands back\n    both what the AI said AND what we double-checked about it.\n    \"\"\"\n    prompt = build_prompt(events, tasks)\n\n    # max_tokens: a full day's plan (three sections plus a possible\n    # overflow one, each a handful of bullets) fits comfortably in 700\n    # tokens. This is also a Haiku-tier task - reorganising a short list\n    # you already gave it is not a job that needs a pricier model.\n    reply = ask_ai(\n        prompt,\n        max_tokens=700,\n        project=\"calendar-task-prioritizer-agent\",\n    )\n\n    plan = split_plan(reply)\n\n    if not plan:\n        raise ValueError(\n            \"The AI replied, but not in the format we asked for.\\n\"\n            \"Run it again - this usually fixes itself.\\n\"\n            \"If it keeps happening, print(reply) to see what came back.\"\n        )\n\n    warnings = check_plan_coverage(plan, tasks)\n\n    return {\"plan\": plan, \"warnings\": warnings, \"raw_reply\": reply}\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check both the parsing AND the\n    # coverage-check logic, using two fake AI replies - one well-formed,\n    # one broken the way a real model occasionally is:\n    #     python prioritizer.py\n    fake_tasks = [\n        \"Finish the Q3 budget review\",\n        \"Reply to the vendor contract email\",\n        \"Review pull request #482\",\n    ]\n\n    good_reply = \"\"\"[MORNING]\n- 09:00-09:15 Team standup\n- Finish the Q3 budget review\n\n[AFTERNOON]\n- 14:30-15:00 Client call\n- Reply to the vendor contract email\n- Review pull request #482\n\n[EVENING]\n- Wind down, nothing else scheduled\n\n[END]\"\"\"\n\n    print(\"--- Well-formed reply ---\")\n    good_plan = split_plan(good_reply)\n    good_warnings = check_plan_coverage(good_plan, fake_tasks)\n    print(f\"Sections found: {list(good_plan.keys())}\")\n    print(f\"Warnings: {good_warnings}\")\n    assert list(good_plan.keys()) == [\"MORNING\", \"AFTERNOON\", \"EVENING\"]\n    assert good_warnings == []\n\n    # A malformed reply: drops \"Review pull request #482\" entirely, and\n    # double-books \"Reply to the vendor contract email\" into two sections.\n    # A real model produces this kind of thing occasionally - the parser\n    # must surface it, not silently hand back an incomplete plan.\n    broken_reply = \"\"\"[MORNING]\n- 09:00-09:15 Team standup\n- Finish the Q3 budget review\n- Reply to the vendor contract email\n\n[AFTERNOON]\n- 14:30-15:00 Client call\n- Reply to the vendor contract email\n\n[END]\"\"\"\n\n    print(\"\\n--- Malformed reply (dropped + double-booked task) ---\")\n    broken_plan = split_plan(broken_reply)\n    broken_warnings = check_plan_coverage(broken_plan, fake_tasks)\n    for warning in broken_warnings:\n        print(f\"  {warning}\")\n\n    assert any(\"DROPPED\" in w and \"pull request #482\" in w for w in broken_warnings)\n    assert any(\"DOUBLE-BOOKED\" in w and \"vendor contract email\" in w for w in broken_warnings)\n    assert len(broken_warnings) == 2\n\n    print(\"\\nAll checks passed.\")\n", "verify": "Run `python prioritizer.py`. The well-formed reply should print `Warnings: []`. The malformed one should print a DOUBLE-BOOKED warning naming the vendor contract email task and a DROPPED warning naming pull request #482, then `All checks passed.`"}], "goFurther": "Break it on purpose: in a Python shell in this folder, build a fake `tasks` list of 15 short, unrelated tasks and an `events` list that's already packed solid (say, six back-to-back 1-hour meetings), then call `plan_day(events, tasks)` for real (this costs a few credits). Does everything land somewhere, with anything that didn't fit named explicitly under `[UNSCHEDULED]`? That's the prompt's own instructions doing the work. Now ask yourself: if the AI reworded a task slightly instead of dropping it (\"Reply to vendor\" instead of \"Reply to the vendor contract email\"), would `check_plan_coverage` still flag it as DROPPED? It would -- incorrectly. Substring matching only survives extra text AROUND a task, not different wording FOR it. That's a real limit of this approach, not a bug you're expected to fix here."}, {"number": 5, "title": "Wire it together and run a real morning plan", "time": "25 min", "description": "Fetching, task-reading, and prioritizing are each already written and tested on their own. This build is only the wiring, plus turning the AI's plan and any coverage warnings into one saved file.", "steps": [{"instruction": "Create `main.py` with this code:", "prompt": "\"\"\"\nCalendar & Task Prioritizer Agent - runs the whole pipeline.\n\nRun with:      python main.py\n\nThis is deliberately a single plain script with no screen to click\n\"Generate\" on (unlike the Social Post Generator's Streamlit app). A\nmorning-planning tool you'd actually want to run automatically - from\ncron on Mac/Linux, or Task Scheduler on Windows - needs to work as a\nscript with no browser tab involved, which is also why it saves the plan\nto a file instead of only printing it.\n\"\"\"\n\nimport datetime\n\nfrom calendar_client import get_today_events\nfrom tasks import get_tasks\nfrom prioritizer import ALL_SECTIONS, plan_day\nfrom sdt_ai import AIError\n\nPLAN_FILE = \"todays_plan.txt\"\n\n# Fixed display order. The AI writes sections in whatever order it\n# chooses, and split_plan() (in prioritizer.py) hands them back as a\n# dict, so relying on dict order would mean today's saved file might\n# read Morning/Evening/Afternoon depending on how the model felt like\n# answering. Pinning the order here means it always reads top-to-bottom.\nDISPLAY_ORDER = ALL_SECTIONS\n\n\ndef render_plan_text(plan, warnings):\n    \"\"\"\n    Turns the {\"MORNING\": ..., ...} dict into one plain-text document,\n    ready to print or save. Pure formatting - no network calls - so it's\n    the one piece of main.py's logic that can be checked with a fake\n    plan below, no live Google or AI account required.\n    \"\"\"\n    today = datetime.date.today().strftime(\"%A, %B %d\")\n    lines = [f\"Your plan for {today}\", \"=\" * 40, \"\"]\n\n    for section in DISPLAY_ORDER:\n        if section not in plan:\n            continue\n        lines.append(section.title())\n        lines.append(\"-\" * len(section))\n        lines.append(plan[section])\n        lines.append(\"\")\n\n    if warnings:\n        lines.append(\"Double-check these before trusting the plan:\")\n        for warning in warnings:\n            lines.append(f\"  - {warning}\")\n        lines.append(\"\")\n\n    return \"\\n\".join(lines)\n\n\ndef main():\n    print(\"Fetching today's calendar events...\")\n    try:\n        events = get_today_events()\n    except FileNotFoundError as problem:\n        # This is the expected failure the first time anyone runs this\n        # without having done the Google Cloud Console setup in Build 1 -\n        # show the friendly message from calendar_client.py, not a stack\n        # trace, and stop cleanly instead of crashing further down.\n        print(problem)\n        return\n    print(f\"Found {len(events)} event(s).\")\n\n    print(\"Reading your task list...\")\n    tasks = get_tasks()\n    print(f\"Found {len(tasks)} task(s).\")\n\n    if not events and not tasks:\n        print(\n            \"Nothing to plan - add events to your Google Calendar or \"\n            \"tasks to tasks.txt, then try again.\"\n        )\n        return\n\n    print(\"Asking the AI to build today's plan...\")\n    try:\n        result = plan_day(events, tasks)\n    except AIError as problem:\n        # Written to be read - show it as-is, same convention as every\n        # other project in this course.\n        print(problem)\n        return\n\n    text = render_plan_text(result[\"plan\"], result[\"warnings\"])\n    print(\"\\n\" + text)\n\n    with open(PLAN_FILE, \"w\", encoding=\"utf-8\") as f:\n        f.write(text)\n    print(f\"Saved to {PLAN_FILE}\")\n\n    if result[\"warnings\"]:\n        print(\n            f\"\\n{len(result['warnings'])} warning(s) above - the AI's plan \"\n            \"didn't fully match your task list. Read them before you rely \"\n            \"on this plan for your day.\"\n        )\n\n\nif __name__ == \"__main__\":\n    # A quick self-check of the pure formatting logic before doing\n    # anything that needs live accounts - if this fails, nothing below\n    # it will work right either, so it's worth 5 lines to catch early.\n    _fake_plan = {\n        \"MORNING\": \"- Standup\",\n        \"UNSCHEDULED\": '- Book dentist appointment (no free slot today)',\n    }\n    _text = render_plan_text(_fake_plan, warnings=['DROPPED: \"Something\" does not appear anywhere in the plan.'])\n    assert \"Morning\" in _text and \"Unscheduled\" in _text and \"DROPPED\" in _text\n    assert \"Afternoon\" not in _text  # sections with nothing in them are skipped entirely\n\n    main()\n", "verify": "Run `python main.py`. Before Build 2's OAuth setup is done, you should see `Fetching today's calendar events...` followed by the friendly `Missing credentials.json.` message -- not a crash. Once Build 2 is done, it fetches your real events, reads (or creates) tasks.txt, asks the AI for a plan, prints it, and saves it to `todays_plan.txt`."}], "goFurther": "Real email sending: add a `mailer.py` using Python's built-in `smtplib` and a Gmail App Password (not your real Gmail password -- generate one at myaccount.google.com/apppasswords), and call it from main.py alongside saving todays_plan.txt. This is exactly what the course description's \"emails you a plan\" line means in a fully wired-up version -- it's left as a stretch here so the core build only needs a Google Calendar account, not a second one for SMTP."}, {"number": 6, "phaseLabel": "🎯 Challenge", "title": "Challenge: Catch the AI when it invents a task you never gave it", "time": "20 min", "description": "The prompt tells the AI not to invent tasks or events you never gave it -- but nothing today actually checks that rule was followed. A hallucinated task is arguably worse than a dropped one: a dropped task is at least invisible, while an invented one looks like real, legitimate work you never asked for. This is the real test of whether you understand how check_plan_coverage works, not just whether main.py runs.", "steps": [{"instruction": "In `prioritizer.py`, add a new function, `find_invented_lines(plan, events, tasks)`, using this as your starting point:", "prompt": "def find_invented_lines(plan, events, tasks):\n    \"\"\"\n    Returns a list of bullet lines from the plan that don't match any\n    given task or event -- the reverse of check_plan_coverage: that\n    function asks \"did every task make it into the plan?\", this one asks\n    \"does everything IN the plan trace back to something we gave it?\"\n\n    A known line is one that contains at least one task's text, or at\n    least one event's summary, as a substring (same matching approach as\n    check_plan_coverage -- reuse that idea here, applied in reverse).\n    \"\"\"\n    known_snippets = [task.lower() for task in tasks]\n    known_snippets += [event[\"summary\"].lower() for event in events]\n\n    invented = []\n    # TODO: loop over every section's text in `plan`, split it into\n    # lines, and keep only the lines that start with \"- \" (real bullets,\n    # not blank lines). For each bullet, check whether it contains ANY\n    # of `known_snippets` as a substring. If none match, the AI added\n    # something nobody gave it -- append that line to `invented`.\n\n    return invented", "verify": "Take the `good_reply` string from prioritizer.py's own self-test and add one extra bullet nobody asked for, e.g. \"- Call the printer about the annual report\" under [AFTERNOON]. Parse it with `split_plan`, then run your `find_invented_lines` against the result with the same `fake_tasks` list and an empty `events` list ([]). It must return exactly that one invented line -- and it must return an empty list when you run it against the ORIGINAL, unmodified `good_reply`."}]}], "portfolio": "You built a morning planning agent that logs into your real Google Calendar, reads your open tasks, and uses Claude to generate a time-blocked daily plan -- with built-in checks that catch the AI if it drops or double-books a task, through your own AI Builder credits with no personal Anthropic subscription or API key required.", "portfolioPrompt": "I just built a Calendar & Task Prioritizer Agent that logs into my real Google Calendar via OAuth, reads my open tasks from a plain-text file, and uses Claude to generate a time-blocked Morning/Afternoon/Evening plan -- with a coverage check that catches the AI if it silently drops or double-books a task before I trust the output.\n\nHelp me write:\n1. A 2-3 sentence project description for my portfolio site\n2. A short LinkedIn post announcing it\n3. Three resume-style bullet points describing what I built and the skills it shows"}$sess$::jsonb,
  null, null,
  $tsh$[{"issue": "Error 403: access_denied on the Google login screen", "fix": "Go to Google Cloud Console -> OAuth consent screen -> Test users, and add your own Google account to the list. Apps left in \"Testing\" mode only allow logins from accounts you've explicitly added there."}, {"issue": "\"No events found\" even though your calendar clearly has events today", "fix": "Check which calendar_id you're querying. \"primary\" is your main calendar -- events on a shared or secondary calendar live under that calendar's own ID, which you can find on that calendar's own Settings page."}, {"issue": "The saved plan is missing a task, or the same task shows up twice", "fix": "This is exactly what check_plan_coverage() in prioritizer.py is for -- read the warnings main.py prints above the plan. A DROPPED or DOUBLE-BOOKED warning means the AI didn't follow the \"every task exactly once\" rule that run; it isn't a bug in your code, it's your code catching a real AI mistake before you trusted a broken plan with your day. Run main.py again -- it usually resolves on a second attempt."}, {"issue": "ModuleNotFoundError when running calendar_client.py or main.py", "fix": "Activate the virtual environment you installed requirements.txt into (or re-run pip install -r requirements.txt) -- the Google API libraries aren't part of the Python standard library, so a fresh terminal without the venv active won't see them."}, {"issue": "token.json exists but you keep getting sent back to the Google login screen", "fix": "Delete token.json and run the login step from Build 2 again. This happens after you revoke access from myaccount.google.com/permissions, or after the refresh token itself expires from long disuse."}]$tsh$::jsonb,
  $res$[{"title": "Google Calendar API overview", "url": "https://developers.google.com/calendar/api/guides/overview"}, {"title": "Calendar API reference: events.list", "url": "https://developers.google.com/calendar/api/v3/reference/events/list"}, {"title": "OAuth 2.0 for Desktop Apps", "url": "https://developers.google.com/identity/protocols/oauth2/native-app"}]$res$::jsonb,
